diff --git a/encryption/encryption.go b/encryption/encryption.go
new file mode 100644
index 0000000..f0857f2
--- /dev/null
+++ b/encryption/encryption.go
@@ -0,0 +1,498 @@
+package encryption
+
+import (
+	"crypto/aes"
+	"crypto/cipher"
+	"crypto/hmac"
+	"crypto/rand"
+	"crypto/sha256"
+	"encoding/base64"
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"hash"
+	"io"
+	"os"
+	"strings"
+	"sync"
+
+	"golang.org/x/crypto/pbkdf2"
+)
+
+const (
+	ChunkSize   = 64 * 1024 // 64KB
+	MagicByte1  = 0x4F
+	MagicByte2  = 0x44
+	VersionByte = 0x01
+
+	KeySourceEnv     = "env"
+	KeySourceFile    = "file"
+	KeySourceLiteral = "literal"
+	KeySourceDerive  = "derive"
+)
+
+var (
+	ErrInvalidKey = errors.New("invalid encryption key: key must be 32 bytes")
+)
+
+type Config struct {
+	Enabled    bool   `yaml:"enabled"`
+	KeySource  string `yaml:"keysource"`
+	KeyEnvVar  string `yaml:"keyenvvar"`
+	KeyFile    string `yaml:"keyfile"`
+	Key        string `yaml:"key"`
+	Passphrase string `yaml:"passphrase"`
+	Salt       string `yaml:"salt"`
+}
+
+func (c Config) Validate() error {
+	if !c.Enabled {
+		return nil
+	}
+
+	src := strings.ToLower(strings.TrimSpace(c.KeySource))
+	if src == "" {
+		return errors.New("key source is required when encryption is enabled")
+	}
+
+	switch src {
+	case KeySourceEnv:
+		if strings.TrimSpace(c.KeyEnvVar) == "" {
+			return errors.New("keyenvvar is required when key source is env")
+		}
+		if strings.TrimSpace(c.KeyFile) != "" || strings.TrimSpace(c.Key) != "" ||
+			strings.TrimSpace(c.Passphrase) != "" || strings.TrimSpace(c.Salt) != "" {
+			return errors.New("key configuration fields are mutually exclusive for env key source")
+		}
+
+	case KeySourceFile:
+		if strings.TrimSpace(c.KeyFile) == "" {
+			return errors.New("keyfile is required when key source is file")
+		}
+		if strings.TrimSpace(c.KeyEnvVar) != "" || strings.TrimSpace(c.Key) != "" ||
+			strings.TrimSpace(c.Passphrase) != "" || strings.TrimSpace(c.Salt) != "" {
+			return errors.New("key configuration fields are mutually exclusive for file key source")
+		}
+
+	case KeySourceLiteral:
+		if strings.TrimSpace(c.Key) == "" {
+			return errors.New("key is required when key source is literal")
+		}
+		if strings.TrimSpace(c.KeyEnvVar) != "" || strings.TrimSpace(c.KeyFile) != "" ||
+			strings.TrimSpace(c.Passphrase) != "" || strings.TrimSpace(c.Salt) != "" {
+			return errors.New("key configuration fields are mutually exclusive for literal key source")
+		}
+
+	case KeySourceDerive:
+		if strings.TrimSpace(c.Passphrase) == "" {
+			return errors.New("passphrase is required when key source is derive")
+		}
+		if strings.TrimSpace(c.Salt) == "" {
+			return errors.New("salt is required when key source is derive")
+		}
+		if strings.TrimSpace(c.KeyEnvVar) != "" || strings.TrimSpace(c.KeyFile) != "" ||
+			strings.TrimSpace(c.Key) != "" {
+			return errors.New("key configuration fields are mutually exclusive for derive key source")
+		}
+
+	default:
+		return fmt.Errorf("unsupported encryption key source: %q", c.KeySource)
+	}
+
+	return nil
+}
+
+func decodeBase64(s string) ([]byte, error) {
+	s = strings.TrimSpace(s)
+	if b, err := base64.StdEncoding.DecodeString(s); err == nil {
+		return b, nil
+	}
+	if b, err := base64.RawStdEncoding.DecodeString(s); err == nil {
+		return b, nil
+	}
+	if b, err := base64.URLEncoding.DecodeString(s); err == nil {
+		return b, nil
+	}
+	return base64.RawURLEncoding.DecodeString(s)
+}
+
+func LoadKey(cfg Config) ([]byte, error) {
+	valCfg := cfg
+	valCfg.Enabled = true
+	if err := valCfg.Validate(); err != nil {
+		return nil, err
+	}
+
+	src := strings.ToLower(strings.TrimSpace(cfg.KeySource))
+	switch src {
+	case KeySourceEnv:
+		val, ok := os.LookupEnv(cfg.KeyEnvVar)
+		if !ok {
+			return nil, fmt.Errorf("encryption key environment variable %q is not set", cfg.KeyEnvVar)
+		}
+		key, err := decodeBase64(val)
+		if err != nil {
+			return nil, fmt.Errorf("failed to decode base64 encryption key from env var %s: %w", cfg.KeyEnvVar, err)
+		}
+		if len(key) != 32 {
+			return nil, fmt.Errorf("%w: encryption key from env var must be 32 bytes, got %d", ErrInvalidKey, len(key))
+		}
+		return key, nil
+
+	case KeySourceFile:
+		data, err := os.ReadFile(cfg.KeyFile)
+		if err != nil {
+			return nil, fmt.Errorf("failed to read encryption key file %q: %w", cfg.KeyFile, err)
+		}
+		trimmed := strings.TrimSpace(string(data))
+		key, err := decodeBase64(trimmed)
+		if err != nil {
+			return nil, fmt.Errorf("failed to decode base64 encryption key from file %s: %w", cfg.KeyFile, err)
+		}
+		if len(key) != 32 {
+			return nil, fmt.Errorf("%w: encryption key from file must be 32 bytes, got %d", ErrInvalidKey, len(key))
+		}
+		return key, nil
+
+	case KeySourceLiteral:
+		trimmed := strings.TrimSpace(cfg.Key)
+		key, err := decodeBase64(trimmed)
+		if err != nil {
+			return nil, fmt.Errorf("failed to decode base64 literal encryption key: %w", err)
+		}
+		if len(key) != 32 {
+			return nil, fmt.Errorf("%w: literal encryption key must be 32 bytes, got %d", ErrInvalidKey, len(key))
+		}
+		return key, nil
+
+	case KeySourceDerive:
+		if cfg.Passphrase == "" {
+			return nil, errors.New("empty passphrase rejected for key derivation")
+		}
+		salt, err := decodeBase64(cfg.Salt)
+		if err != nil {
+			return nil, fmt.Errorf("failed to decode base64 salt: %w", err)
+		}
+		if len(salt) < 16 {
+			return nil, fmt.Errorf("encryption salt must be at least 16 bytes, got %d", len(salt))
+		}
+		derivedKey := pbkdf2.Key([]byte(cfg.Passphrase), salt, 100000, 32, sha256.New)
+		return derivedKey, nil
+
+	default:
+		return nil, fmt.Errorf("unsupported encryption key source: %q", cfg.KeySource)
+	}
+}
+
+type Encryptor struct {
+	key []byte
+}
+
+func NewEncryptor(key []byte) (*Encryptor, error) {
+	if len(key) != 32 {
+		return nil, fmt.Errorf("%w: key must be 32 bytes, got %d", ErrInvalidKey, len(key))
+	}
+	keyCopy := make([]byte, 32)
+	copy(keyCopy, key)
+	return &Encryptor{key: keyCopy}, nil
+}
+
+func (e *Encryptor) EncryptWriter(w io.Writer) io.WriteCloser {
+	block, err := aes.NewCipher(e.key)
+	if err != nil {
+		// e.key is validated to be 32 bytes, so aes.NewCipher will not fail
+		panic(err)
+	}
+	gcm, err := cipher.NewGCM(block)
+	if err != nil {
+		panic(err)
+	}
+
+	return &encryptWriter{
+		w:   w,
+		key: e.key,
+		gcm: gcm,
+		h:   hmac.New(sha256.New, e.key),
+		buf: make([]byte, 0, ChunkSize),
+	}
+}
+
+func (e *Encryptor) DecryptReader(r io.Reader) (io.Reader, error) {
+	return DecryptReader(r, e.key)
+}
+
+type encryptWriter struct {
+	w             io.Writer
+	key           []byte
+	gcm           cipher.AEAD
+	h             hash.Hash
+	buf           []byte
+	headerWritten bool
+	closed        bool
+	err           error
+	mu            sync.Mutex
+}
+
+func (ew *encryptWriter) ensureHeader() error {
+	if !ew.headerWritten {
+		header := []byte{MagicByte1, MagicByte2, VersionByte}
+		if _, err := ew.w.Write(header); err != nil {
+			return err
+		}
+		ew.headerWritten = true
+	}
+	return nil
+}
+
+func (ew *encryptWriter) Write(p []byte) (int, error) {
+	ew.mu.Lock()
+	defer ew.mu.Unlock()
+
+	if ew.closed {
+		return 0, errors.New("write to closed encryptWriter")
+	}
+	if ew.err != nil {
+		return 0, ew.err
+	}
+
+	if err := ew.ensureHeader(); err != nil {
+		ew.err = err
+		return 0, err
+	}
+
+	total := len(p)
+	for len(p) > 0 {
+		space := ChunkSize - len(ew.buf)
+		if len(p) < space {
+			ew.buf = append(ew.buf, p...)
+			break
+		}
+		ew.buf = append(ew.buf, p[:space]...)
+		p = p[space:]
+		if err := ew.flushChunk(); err != nil {
+			ew.err = err
+			return 0, err
+		}
+	}
+
+	return total, nil
+}
+
+func (ew *encryptWriter) flushChunk() error {
+	if len(ew.buf) == 0 {
+		return nil
+	}
+
+	nonce := make([]byte, ew.gcm.NonceSize())
+	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
+		return fmt.Errorf("failed to generate random nonce: %w", err)
+	}
+
+	ciphertext := ew.gcm.Seal(nil, nonce, ew.buf, nil)
+	payloadLen := uint32(len(nonce) + len(ciphertext))
+
+	var lenBuf [4]byte
+	binary.BigEndian.PutUint32(lenBuf[:], payloadLen)
+
+	if _, err := ew.w.Write(lenBuf[:]); err != nil {
+		return err
+	}
+	ew.h.Write(lenBuf[:])
+
+	if _, err := ew.w.Write(nonce); err != nil {
+		return err
+	}
+	ew.h.Write(nonce)
+
+	if _, err := ew.w.Write(ciphertext); err != nil {
+		return err
+	}
+	ew.h.Write(ciphertext)
+
+	ew.buf = ew.buf[:0]
+	return nil
+}
+
+func (ew *encryptWriter) Close() error {
+	ew.mu.Lock()
+	defer ew.mu.Unlock()
+
+	if ew.closed {
+		return nil
+	}
+	ew.closed = true
+
+	if ew.err != nil {
+		return ew.err
+	}
+
+	if err := ew.ensureHeader(); err != nil {
+		ew.err = err
+		return err
+	}
+
+	if len(ew.buf) > 0 {
+		if err := ew.flushChunk(); err != nil {
+			ew.err = err
+			return err
+		}
+	}
+
+	var sentinel [4]byte // 4 zero bytes
+	if _, err := ew.w.Write(sentinel[:]); err != nil {
+		ew.err = err
+		return err
+	}
+
+	mac := ew.h.Sum(nil)
+	if _, err := ew.w.Write(mac); err != nil {
+		ew.err = err
+		return err
+	}
+
+	return nil
+}
+
+func DecryptReader(r io.Reader, key []byte) (io.Reader, error) {
+	if len(key) != 32 {
+		return nil, fmt.Errorf("%w: key must be 32 bytes, got %d", ErrInvalidKey, len(key))
+	}
+	keyCopy := make([]byte, 32)
+	copy(keyCopy, key)
+	return &decryptReader{
+		r:   r,
+		key: keyCopy,
+	}, nil
+}
+
+type decryptReader struct {
+	r           io.Reader
+	key         []byte
+	gcm         cipher.AEAD
+	h           hash.Hash
+	buf         []byte
+	initialized bool
+	finished    bool
+	mu          sync.Mutex
+}
+
+func (dr *decryptReader) init() error {
+	if len(dr.key) != 32 {
+		return fmt.Errorf("%w: key must be 32 bytes, got %d", ErrInvalidKey, len(dr.key))
+	}
+
+	header := make([]byte, 3)
+	_, err := io.ReadFull(dr.r, header)
+	if err != nil {
+		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
+			return fmt.Errorf("truncated data: failed to read header: %w", err)
+		}
+		return err
+	}
+
+	if header[0] != MagicByte1 || header[1] != MagicByte2 {
+		return fmt.Errorf("invalid header: expected magic 0x4F 0x44, got 0x%02X 0x%02X", header[0], header[1])
+	}
+
+	if header[2] != VersionByte {
+		return fmt.Errorf("unsupported version: expected 0x01, got 0x%02X", header[2])
+	}
+
+	block, err := aes.NewCipher(dr.key)
+	if err != nil {
+		return fmt.Errorf("failed to create cipher: %w", err)
+	}
+
+	gcm, err := cipher.NewGCM(block)
+	if err != nil {
+		return fmt.Errorf("failed to create GCM: %w", err)
+	}
+
+	dr.gcm = gcm
+	dr.h = hmac.New(sha256.New, dr.key)
+	dr.initialized = true
+	return nil
+}
+
+func (dr *decryptReader) Read(p []byte) (int, error) {
+	dr.mu.Lock()
+	defer dr.mu.Unlock()
+
+	if !dr.initialized {
+		if err := dr.init(); err != nil {
+			return 0, err
+		}
+	}
+
+	if len(dr.buf) > 0 {
+		n := copy(p, dr.buf)
+		dr.buf = dr.buf[n:]
+		return n, nil
+	}
+
+	if dr.finished {
+		return 0, io.EOF
+	}
+
+	for {
+		var lenBuf [4]byte
+		_, err := io.ReadFull(dr.r, lenBuf[:])
+		if err != nil {
+			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
+				return 0, fmt.Errorf("truncated data: unexpected end of stream waiting for chunk length: %w", err)
+			}
+			return 0, err
+		}
+
+		chunkLen := binary.BigEndian.Uint32(lenBuf[:])
+		if chunkLen == 0 {
+			// Zero sentinel reached! Read 32-byte HMAC
+			var hmacBuf [32]byte
+			_, err := io.ReadFull(dr.r, hmacBuf[:])
+			if err != nil {
+				return 0, fmt.Errorf("truncated data: failed to read HMAC: %w", err)
+			}
+
+			expectedHMAC := dr.h.Sum(nil)
+			if !hmac.Equal(hmacBuf[:], expectedHMAC) {
+				return 0, errors.New("integrity check failed: HMAC mismatch")
+			}
+
+			dr.finished = true
+			return 0, io.EOF
+		}
+
+		// Minimum chunk payload: 12 (nonce) + 16 (tag) = 28 bytes
+		if chunkLen < 28 {
+			return 0, fmt.Errorf("invalid chunk length: %d", chunkLen)
+		}
+
+		dr.h.Write(lenBuf[:])
+
+		chunkData := make([]byte, chunkLen)
+		_, err = io.ReadFull(dr.r, chunkData)
+		if err != nil {
+			return 0, fmt.Errorf("truncated data: failed to read chunk: %w", err)
+		}
+
+		dr.h.Write(chunkData)
+
+		nonce := chunkData[:12]
+		ciphertextAndTag := chunkData[12:]
+
+		plaintext, err := dr.gcm.Open(nil, nonce, ciphertextAndTag, nil)
+		if err != nil {
+			return 0, fmt.Errorf("decryption failed: %w", err)
+		}
+
+		if len(plaintext) == 0 {
+			continue
+		}
+
+		n := copy(p, plaintext)
+		if n < len(plaintext) {
+			dr.buf = plaintext[n:]
+		}
+		return n, nil
+	}
+}
diff --git a/encryption/encryption_test.go b/encryption/encryption_test.go
