index 0000000..2b040c4
--- /dev/null
+++ b/encryption/encryption_test.go
@@ -0,0 +1,450 @@
+package encryption
+
+import (
+	"bytes"
+	"compress/gzip"
+	"crypto/rand"
+	"encoding/base64"
+	"encoding/binary"
+	"errors"
+	"io"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+
+	"github.com/stretchr/testify/assert"
+	"github.com/stretchr/testify/require"
+)
+
+func generateRandomBytes(n int) []byte {
+	b := make([]byte, n)
+	_, _ = rand.Read(b)
+	return b
+}
+
+func TestNewEncryptor_KeyValidation(t *testing.T) {
+	// Rejects non-32-byte keys, error wraps ErrInvalidKey
+	invalidLengths := []int{0, 1, 16, 24, 31, 33, 64}
+	for _, l := range invalidLengths {
+		key := make([]byte, l)
+		enc, err := NewEncryptor(key)
+		assert.Nil(t, enc, "expected nil encryptor for length %d", l)
+		require.Error(t, err, "expected error for length %d", l)
+		assert.True(t, errors.Is(err, ErrInvalidKey), "error must wrap ErrInvalidKey for length %d", l)
+	}
+
+	validKey := make([]byte, 32)
+	enc, err := NewEncryptor(validKey)
+	assert.NoError(t, err)
+	assert.NotNil(t, enc)
+}
+
+func TestEncryptWriter_Format(t *testing.T) {
+	key := generateRandomBytes(32)
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	plaintext := []byte("Hello, World! This is a test of AES-256-GCM chunked streaming encryption.")
+	var buf bytes.Buffer
+	w := enc.EncryptWriter(&buf)
+
+	n, err := w.Write(plaintext)
+	assert.NoError(t, err)
+	assert.Equal(t, len(plaintext), n)
+
+	err = w.Close()
+	assert.NoError(t, err)
+
+	// Idempotent close
+	err = w.Close()
+	assert.NoError(t, err)
+
+	data := buf.Bytes()
+	// Must start with 3-byte header: 0x4F 0x44 0x01
+	require.True(t, len(data) >= 3+4+12+16+4+32)
+	assert.Equal(t, byte(0x4F), data[0])
+	assert.Equal(t, byte(0x44), data[1])
+	assert.Equal(t, byte(0x01), data[2])
+
+	// First chunk length prefix (4 bytes big-endian)
+	chunkLen := binary.BigEndian.Uint32(data[3:7])
+	expectedChunkLen := uint32(12 + len(plaintext) + 16)
+	assert.Equal(t, expectedChunkLen, chunkLen)
+
+	// After chunk, should be zero sentinel (4 zero bytes)
+	offset := 7 + int(chunkLen)
+	sentinel := binary.BigEndian.Uint32(data[offset : offset+4])
+	assert.Equal(t, uint32(0), sentinel)
+
+	// Followed by 32-byte HMAC
+	hmacBytes := data[offset+4 : offset+4+32]
+	assert.Len(t, hmacBytes, 32)
+	assert.Equal(t, len(data), offset+4+32)
+}
+
+func TestEncryptWriter_EmptyPlaintext(t *testing.T) {
+	key := generateRandomBytes(32)
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	var buf bytes.Buffer
+	w := enc.EncryptWriter(&buf)
+	err = w.Close()
+	assert.NoError(t, err)
+
+	data := buf.Bytes()
